sourcesContent:
.how {
  background: var(--bg-soft);
  border-block: 1px solid var(--border);
}

.how-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: clamp(44px, 7vw, 96px);
  align-items: center;
}

.how-cta {
  margin-top: 34px;
}

.how-steps {
  display: flex;
  flex-direction: column;
}

.how-step {
  display: flex;
  gap: 24px;
  padding: 30px 0;
  border-bottom: 1px solid var(--border);
}

.how-step:first-child {
  padding-top: 0;
}

.how-step:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.how-step-number {
  flex: none;
  font-family: var(--font-display);
  font-style: italic;
  font-size: 30px;
  color: var(--gold);
  line-height: 1.1;
  width: 52px;
}

.how-step-title {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 600;
}

.how-step-text {
  font-size: 14.5px;
  color: var(--text-muted);
  margin-top: 8px;
  max-width: 420px;
}

@media (max-width: 900px) {
  .how-grid {
    grid-template-columns: 1fr;
  }

  .how-step {
    padding: 24px 0;
  }
}
